import{F as s}from"./chunks/FigureContainer.VL3Ntwlh.js";import{H as i}from"./chunks/HighLightText.D0qzB827.js";import{R as e}from"./chunks/ResourceCard.DSyPPpy0.js";import{c as p,o as d,a as l,b as o,d as a,e as n,w as r}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                                               *//* empty css                                                             *//* empty css                                                                            */const S=JSON.parse('{"title":"AI基础概念入门：核心概念解析","description":"梳理人工智能、机器学习、神经网络、深度学习与大语言模型的五层同心圆结构，对比监督、无监督、强化学习三种训练范式，概览 CV、NLP、语音、推荐四大应用领域，并解析传统机器学习与神经网络模型的形态差异。","frontmatter":{"date":"2026-06-20T13:36:01.000Z","title":"AI基础概念入门：核心概念解析","tldr":"从 AI 到大语言模型是五层同心圆，理解这层嵌套关系是入门 AI 的第一把钥匙。","description":"梳理人工智能、机器学习、神经网络、深度学习与大语言模型的五层同心圆结构，对比监督、无监督、强化学习三种训练范式，概览 CV、NLP、语音、推荐四大应用领域，并解析传统机器学习与神经网络模型的形态差异。","coverImg":"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/ai_inner_link.png","tags":["AI","ML","深度学习","LLM"],"categories":["大模型基础","基础入门"],"permalink":"/llm-basic/ai-concepts-introduction"},"headers":[],"relativePath":"llm-basic/ai-concepts-introduction.md","filePath":"22.大模型基础/01.基础入门/01.AI基础概念入门.md"}'),u={name:"llm-basic/ai-concepts-introduction.md"},k=Object.assign(u,{setup(g){return(m,t)=>(d(),p("div",null,[t[16]||(t[16]=l("h1",{id:"ai基础概念入门-核心概念解析",tabindex:"-1"},[n("AI基础概念入门：核心概念解析 "),l("a",{class:"header-anchor",href:"#ai基础概念入门-核心概念解析","aria-label":"Permalink to “AI基础概念入门：核心概念解析”"},"​")],-1)),t[17]||(t[17]=l("blockquote",null,[l("p",null,[l("strong",null,"摘要"),n("：AI 领域术语天然嵌套层叠，初学者容易迷失在概念丛林中。本文以五层同心圆为框架，从最外层的人工智能逐步收敛至最内层的大语言模型，系统梳理了 AI、机器学习、神经网络、深度学习与 LLM 之间的层级关系。在此基础上，逐一拆解监督学习、无监督学习、强化学习三种训练范式的本质差异，并解释了 LLM 预训练为何采用自监督学习这一特殊形式。进一步概览计算机视觉、自然语言处理、语音处理与推荐系统四大应用领域，对比传统机器学习与神经网络在数据类型与特征工程上的根本分歧。最终构建出一张完整的 AI 基础概念地图，帮助读者在面对任何 AI 术语时能迅速定位其在版图中的坐标。")])],-1)),o(e,{resource:{name:"图集速览：AI 核心概念图解",description:"如果你对这些概念还比较陌生，建议先读这篇图集速览。用一张五层同心圆图，帮你快速理清 AI、机器学习、神经网络、深度学习与大语言模型之间的层级关系。",url:"https://mp.weixin.qq.com/s/HemiMmh-KuqwQyGToFxFvQ",type:"article",tags:["AI","大模型基础"]}}),t[18]||(t[18]=a('<h2 id="_1-引言" tabindex="-1">1. 引言 <a class="header-anchor" href="#_1-引言" aria-label="Permalink to “1. 引言”">​</a></h2><p>2016 年 AlphaGo 战胜李世石的时候，我们都说：&quot;人工智能要取代人类了&quot;。十年过去了，2026 年的今天，你用 ChatGPT 写邮件、让 Claude 帮你 debug、刷着 AI 生成的短视频——人工智能没有取代人类，但它已经像水电一样渗进了我们的日常。可如果你去问一个刚开始接触 AI 的人&quot;AI 和机器学习到底什么关系&quot;、&quot;大语言模型为什么叫大语言模型&quot;，多半会得到一段支支吾吾的回答。</p><p>这不是任何人的问题。AI 领域的概念天然就是嵌套的、层叠的，一个术语套着另一个术语，初学者很容易迷失。但这层窗户纸其实特别好捅破——真正需要理解的核心概念，一只手数得过来。</p><h2 id="_2-ai-是什么" tabindex="-1">2. AI 是什么？ <a class="header-anchor" href="#_2-ai-是什么" aria-label="Permalink to “2. AI 是什么？”">​</a></h2><p><strong>人工智能（Artificial Intelligence）</strong>是研究、开发用于模拟、延伸和扩展人的智能的理论、方法、技术及应用的一门技术科学。这句话的重点在「模拟、延伸和扩展」——它不是在造人，而是在做一件更务实的事：让机器在某些智力任务上表现得像人，甚至超过人。</p><p>仅有这个定义是不够的，因为它太宽泛了。一个下棋的程序是 AI，一段识别猫的代码也是 AI，ChatGPT 更是 AI——它们显然不是同一个东西。所以需要一套层级结构来区分。让我们用一张同心圆把 AI 的版图摊开，然后沿着学习方式、任务类型、模型形态三条线索，把整幅地图标记清楚。</p><div class="note custom-block github-alert"><p class="custom-block-title">关键理解</p><p></p><p>LLM 不是凭空产生的，它是 AI 这个大树干上最新、最粗壮的一根枝条。理解神经网络，就是理解 LLM 的&quot;血肉&quot;。</p></div>',7)),o(s,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/ai_inner_link.png",caption:""}),t[19]||(t[19]=a('<p>AI 领域的核心概念天然构成一组同心圆，最外面一圈最大、最模糊，越往里越具体、越聚焦。从外到内依次是：</p><ul><li><strong>人工智能（AI）</strong>：让机器表现出智能行为的广义科学。这是一个目标，不是一种方法。</li><li><strong>机器学习（ML）</strong>：不靠显式编程，让机器从数据中自动学习规律。这是实现 AI 的主流路径。</li><li><strong>神经网络（NN）</strong>：模仿人脑神经元结构，用层级方式处理信息。这是机器学习中的一类模型。</li><li><strong>深度学习（DL）</strong>：多层神经网络，能自动从原始数据中提取越来越抽象的特征。代表模型包括 CNN、RNN、Transformer。</li><li><strong>大语言模型（LLM）</strong>：基于 Transformer 架构的超大规模神经网络，专攻语言理解与生成。GPT、Claude、DeepSeek、Qwen 都属于这一类。</li></ul><p>理解了这个嵌套关系，AI 领域的术语就不再是一堆散落的词，而是一棵有根有干有枝条的树。LLM 不是凭空冒出来的，它是这棵树上最新、最粗壮的一根枝条。</p><table tabindex="0"><thead><tr><th>概念</th><th>一句话定义</th><th>典型方法/模型</th></tr></thead><tbody><tr><td><strong>AI</strong></td><td>让机器变聪明的科学</td><td>搜索、推理、规划、学习等</td></tr><tr><td><strong>机器学习</strong></td><td>从数据中自动学习规律</td><td>决策树、SVM、神经网络等</td></tr><tr><td><strong>深度学习</strong></td><td>用多层神经网络自动提取特征</td><td>CNN、RNN、Transformer</td></tr><tr><td><strong>大语言模型</strong></td><td>用深度学习的超大 Transformer 做语言任务</td><td>GPT、Claude、DeepSeek、Qwen</td></tr></tbody></table><h2 id="_3-ai-怎么学-——-三种训练学习范式" tabindex="-1">3. AI 怎么学 —— 三种训练学习范式 <a class="header-anchor" href="#_3-ai-怎么学-——-三种训练学习范式" aria-label="Permalink to “3. AI 怎么学 —— 三种训练学习范式”">​</a></h2><p>知道了 AI 是什么，下一个问题自然是<strong>怎么做到的</strong>。AI 的学习方式分三种，这个分类决定了模型的训练成本和能力边界。</p>',6)),o(s,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/ai_learning_mode.png",caption:""}),t[20]||(t[20]=l("ul",null,[l("li",null,[l("p",null,[l("strong",null,"监督学习（Supervised Learning）—— 有老师带"),n("。 训练数据带有标签，模型学习从输入到输出的映射关系。比如标注一千张猫和狗的图片，让模型学会「长这样的叫猫，长那样的叫狗」。这是最成熟、应用最广的范式，典型算法包括线性回归、决策树、SVM 和神经网络本身。")])]),l("li",null,[l("p",null,[l("strong",null,"无监督学习（Unsupervised Learning）—— 自己摸索"),n("。 数据没有标签，模型自己去发现内在的结构和分布。比如给你一堆客户数据但不告诉你谁是谁，算法自动发现这些客户天然聚成了三个群。K-Means、DBSCAN、PCA 是这里的主力。")])]),l("li",null,[l("p",null,[l("strong",null,"强化学习（Reinforcement Learning）—— 试错中成长"),n("。 模型在一个环境中行动，根据结果获得奖励或惩罚，逐步学会什么动作能最大化长期回报。AlphaGo 下围棋就是这个逻辑：每一步棋本身没有对错标签，但最终赢了就是正向信号，输了就是负向信号，模型通过海量对弈慢慢摸索出最优策略。")])])],-1)),l("p",null,[t[1]||(t[1]=n("值得注意的是，",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[0]||(t[0]=[n("LLM 的预训练是自监督学习（Self-Supervised Learning），属于无监督学习的一种特殊形式：从文本本身构造监督信号（用前文预测下一个词），不需要人工标注",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[21]||(t[21]=l("h2",{id:"_4-llm-为什么是无监督的",tabindex:"-1"},[n("4. LLM 为什么是无监督的？ "),l("a",{class:"header-anchor",href:"#_4-llm-为什么是无监督的","aria-label":"Permalink to “4. LLM 为什么是无监督的？”"},"​")],-1)),t[22]||(t[22]=l("p",null,"监督学习最大的痛点是标签——人工标注贵得要命。标注 1000 张猫狗图片还行，标注一亿条中文文本的情感正负？一来成本不可承受，二来很多文本的「标签」本身就模糊。",-1)),t[23]||(t[23]=l("p",null,[n("LLM 的预训练绕开了这个问题，用的是一种叫自监督学习（Self-Supervised Learning）的技术："),l("strong",null,"标签不需要人来标注，文本自己就是标签"),n("。")],-1)),l("p",null,[t[4]||(t[4]=n("原理简单得让人意外：",-1)),o(i,{type:"info",bold:""},{default:r(()=>[...t[3]||(t[3]=[n("从任意一段文本里截取前半句作为输入，后面的一个字作为目标，让模型去预测",-1)])]),_:1}),t[5]||(t[5]=n("。比如语料库里有一句「今天天气真好，适合出去散步」，训练时就拆成：",-1))]),t[24]||(t[24]=l("blockquote",null,[l("p",null,"输入：「今天天气真」→ 目标：「好」"),l("p",null,"输入：「今天天气真好」→ 目标：「，」")],-1)),t[25]||(t[25]=l("p",null,"不需要任何人工标注，把海量原始文本直接扔进去，模型自己构造监督信号。这就是为什么 GPT 系列能用几乎整个互联网的文本做训练——标签成本是零。",-1)),t[26]||(t[26]=l("p",null,"所以「无监督」不是没有监督信号，而是不需要人类标注数据。这个区别决定了 LLM 能长到今天的规模：数据的瓶颈被拆掉了。",-1)),t[27]||(t[27]=l("h2",{id:"_5-ai-能做什么-——-四大应用领域",tabindex:"-1"},[n("5. AI 能做什么？—— 四大应用领域 "),l("a",{class:"header-anchor",href:"#_5-ai-能做什么-——-四大应用领域","aria-label":"Permalink to “5. AI 能做什么？—— 四大应用领域”"},"​")],-1)),t[28]||(t[28]=l("p",null,"理解了 AI 怎么学，让我们再看看它到底能干哪些事，AI 的应用大致落在以下四个主要领域：",-1)),o(s,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/ai_apply_domain.png",caption:""}),t[29]||(t[29]=a('<ul><li><p><strong>计算机视觉（CV）：让机器&quot;看懂&quot;</strong>。 图像识别告诉你图片里有什么，目标检测还能框出物体在哪，图像生成（Stable Diffusion、DALL·E）则反过来——根据文字描述画出一张图。</p></li><li><p><strong>自然语言处理（NLP）：让机器&quot;理解&quot;和&quot;生成&quot;语言</strong>。 这是 LLM 的主战场。文本分类、情感分析、机器翻译、阅读理解、多轮对话——这些下游任务背后是同一个核心能力：理解语言的语义结构，并生成连贯的回复。GPT、Claude、DeepSeek 的日常聊天能力就来自这里。</p></li><li><p><strong>语音处理：让机器&quot;听懂&quot;和&quot;说出&quot;</strong>。 语音识别（ASR）把语音转成文字——Whisper 支持约 99 种语言，Qwen3-ASR 在中文和方言场景抗噪能力尤为突出；语音合成（TTS）反过来把文字变成自然的语音，dots.tts 和 Kokoro 在开源社区质量突出。</p></li><li><p><strong>推荐系统：分析行为，预测兴趣</strong>。 根据你的浏览、购买、点击历史，推荐你可能感兴趣的商品、视频或文章。抖音的推荐算法和淘宝的猜你喜欢，背后都是这套逻辑。</p></li></ul><p>四个领域分工明确，但近年来融合的趋势越来越明显。GPT-4 和 Gemini 这样的模型已经能同时处理图像、文本和语音，这<strong>恰恰说明底层的学习范式是通用的</strong>。</p><h2 id="_6-传统机器学习-vs-神经网络" tabindex="-1">6. 传统机器学习 vs 神经网络 <a class="header-anchor" href="#_6-传统机器学习-vs-神经网络" aria-label="Permalink to “6. 传统机器学习 vs 神经网络”">​</a></h2><p>最后一条线索是模型本身的形态演变。AI 领域有两类截然不同的模型，理解它们的区别，你就能读懂这个行业过去二十年的技术走向。</p>',4)),o(s,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/ml_vs_network.png",caption:""}),l("ul",null,[l("li",null,[l("p",null,[t[8]||(t[8]=l("strong",null,"传统 ML 模型",-1)),t[9]||(t[9]=n("，包括逻辑回归、决策树、SVM、朴素贝叶斯等，",-1)),o(i,{type:"info",bold:""},{default:r(()=>[...t[6]||(t[6]=[n("擅长处理结构化数据，也就是整齐的表格数据",-1)])]),_:1}),t[10]||(t[10]=n("。比如根据用户的年龄、收入、历史信用预测违约概率，传统 ML 做得干净利落。但这类模型有一个硬伤：",-1)),o(i,{bold:""},{default:r(()=>[...t[7]||(t[7]=[n("需要人工做特征工程，你得先告诉模型「年龄很重要」「月收入比总资产更关键」，模型才能发挥",-1)])]),_:1}),t[11]||(t[11]=n("。",-1))])]),l("li",null,[l("p",null,[t[13]||(t[13]=l("strong",null,"神经网络模型",-1)),t[14]||(t[14]=n("，包括卷积神经网络（CNN）、循环神经网络（RNN）、Transformer等，",-1)),o(i,{type:"info",bold:""},{default:r(()=>[...t[12]||(t[12]=[n("专攻非结构化数据：图像、文本、语音。它们不需要你手动提取特征，自己会在层层运算中学会从像素里认出边缘、从边缘里认出形状、从形状里认出猫脸",-1)])]),_:1}),t[15]||(t[15]=n("。Transformer 把这个能力推到了极致：让每个 token 直接和序列中的所有其他 token 交互，并行计算，一次性理解整段文本。",-1))])])]),t[30]||(t[30]=a('<p>传统 ML 到今天仍然有用，尤其在可解释性要求高的场景（金融风控、医疗诊断）。但如果你想知道 ChatGPT 为什么能写出一段通顺的回答，答案不在逻辑回归里，而是在 Transformer 的 Attention 机制里。</p><h2 id="_7-总结" tabindex="-1">7. 总结 <a class="header-anchor" href="#_7-总结" aria-label="Permalink to “7. 总结”">​</a></h2><p>从最外层的 AI，到最内层的大语言模型——你已经完整走过了 AI 基础概念的版图。让我们来盘点你带走的关键装备：</p><ul><li><strong>层级关系</strong>：AI → 机器学习 → 神经网络 → 深度学习 → 大语言模型，像一个五层同心圆，每层都是前一层的一个子集。</li><li><strong>学习方式</strong>：监督学习有老师，无监督自己摸索，强化学习试错成长。LLM 的预训练用的是自监督，站在无监督的肩膀上。</li><li><strong>任务类型</strong>：CV 看图、NLP 读文、语音听说、推荐猜你——这四个主战场上，NLP 是 LLM 的天然领地。</li><li><strong>模型形态</strong>：传统 ML 擅长表格数据，神经网络统治非结构化数据，而 Transformer 是它的高峰。</li></ul><p>记住这些概念不是为了背它们，而是为了在听到「自监督预训练」或「Transformer 的 Attention」时，你能立刻定位它在 AI 版图的哪个位置、该往哪个方向深究。</p>',5))]))}});export{S as __pageData,k as default};
